layer.css:
[data-ryt="footer"] { color: var(--ryt-header-text); background-color: var(--ryt-header-bg); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="pitch"] { color: rgb(85, 85, 85); background-color: rgba(131, 134, 150, 0.1); border-left: 3px solid rgba(131, 134, 150, 0.6); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 15.36px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(85, 85, 85); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 1px; padding-right: 23.04px; padding-bottom: 1px; padding-left: 23.04px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 5px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.25s }
[data-ryt="hero"] h1 { color: rgb(0, 0, 0); font-family: var(--ryt-font-heading); font-size: 26.88px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 0, 0); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-header-text); border-radius: 0px; box-shadow: rgba(0, 0, 0, 0) 0px 2px 0px 0px; font-family: var(--ryt-font-heading); font-size: 20.736px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.25s }
[data-ryt="header"] { box-shadow: rgba(131, 134, 150, 0.1) 0px -1px 0px 0px inset, rgba(131, 134, 150, 0.1) 0px 0px 15.36px 0px, rgba(0, 0, 0, 0) 0px 0px 0px 1px }
[data-ryt="nav"] a { color: var(--ryt-header-text); border-radius: 0px; box-shadow: rgba(0, 0, 0, 0) 0px 2px 0px 0px; font-family: var(--ryt-font-heading); font-size: 15.36px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: 0.25s }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: rgb(131, 134, 150); font-family: var(--ryt-font-heading); font-size: 16.896px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(131, 134, 150); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: rgb(0, 0, 0); border-radius: 5px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 0, 0); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.25s }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(0, 0, 0); border-radius: 5px; font-family: var(--ryt-font-heading); font-size: 16.896px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 0, 0); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.25s }
[data-ryt="rec-card"] [data-ryt="title"]:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: inherit; text-decoration-thickness: inherit; text-decoration-style: inherit; text-decoration-color: inherit }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: inherit; text-decoration-thickness: inherit; text-decoration-style: inherit; text-decoration-color: inherit }
[data-ryt="nav"] a:hover { box-shadow: 0px 2px }
[data-ryt="brand"]:hover { box-shadow: 0px 2px }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
